CREATE TEMP TABLE w ON COMMIT DROP AS SELECT c.cnpj_orgao org, c.categoria_saude cat, r.ni_fornecedor forn, CASE WHEN i.valor_unitario_estimado > 0 AND r.valor_unitario_homologado <> i.valor_unitario_estimado AND r.valor_unitario_homologado / i.valor_unitario_estimado > 0.05 AND r.valor_unitario_homologado / i.valor_unitario_estimado <= 1.5 THEN 1 END valido FROM resultados r JOIN itens i ON i.numero_controle_pncp = r.numero_controle_pncp AND i.numero_item = r.numero_item JOIN contratacoes c ON c.numero_controle_pncp = r.numero_controle_pncp WHERE c.modalidade_nome LIKE 'Pregão%' AND r.valor_unitario_homologado > 0 AND r.data_resultado >= current_date - 730;
-- Q26 cobertura por licitação aberta (pregão): desconto (org+cat, >=30 válidos) e concorrentes (org+cat, >=10 itens e >=3 vencedores)
WITH ab AS (SELECT c.cnpj_orgao org, c.categoria_saude cat, c.valor_total_estimado vt, c.esfera FROM contratacoes c WHERE c.data_encerramento_proposta >= current_date AND c.modalidade_nome LIKE 'Pregão%' AND NOT EXISTS (SELECT 1 FROM resultados r WHERE r.numero_controle_pncp = c.numero_controle_pncp)),
oc AS (SELECT org, cat, count(valido) nv, count(*) ni, count(DISTINCT forn) nf FROM w GROUP BY 1,2)
SELECT count(*) abertas, count(*) FILTER (WHERE nv >= 30) desconto, count(*) FILTER (WHERE ni >= 10 AND nf >= 3) concorrentes, count(*) FILTER (WHERE nv >= 30 OR (ni >= 10 AND nf >= 3)) algum_bloco, round(100.0*sum(vt) FILTER (WHERE ni >= 10 AND nf >= 3)/nullif(sum(vt),0),1) pct_valor_concorrentes, round(100.0*sum(vt) FILTER (WHERE nv >= 30)/nullif(sum(vt),0),1) pct_valor_desconto FROM ab LEFT JOIN oc USING (org, cat);
-- Q27 mesma coisa por categoria
WITH ab AS (SELECT c.cnpj_orgao org, c.categoria_saude cat FROM contratacoes c WHERE c.data_encerramento_proposta >= current_date AND c.modalidade_nome LIKE 'Pregão%' AND NOT EXISTS (SELECT 1 FROM resultados r WHERE r.numero_controle_pncp = c.numero_controle_pncp)), oc AS (SELECT org, cat, count(valido) nv, count(*) ni, count(DISTINCT forn) nf FROM w GROUP BY 1,2)
SELECT ab.cat, count(*) abertas, round(100.0*count(*) FILTER (WHERE nv >= 30)/count(*),0) pct_desconto, round(100.0*count(*) FILTER (WHERE ni >= 10 AND nf >= 3)/count(*),0) pct_concorrentes FROM ab LEFT JOIN oc USING (org, cat) GROUP BY ab.cat ORDER BY abertas DESC
